// Second authored batch. The first forty revisions remain unchanged.
module.exports={
'SRC26-004':{
 reason:'Bỏ dẫn sẵn điều loại trừ; nhiễu dựa vào sự khác nhau giữa bản sao, thời gian thực tập và hiệu lực quyết định.',
 variants:[
  'Tháng 10/2026, A nộp bản sao quyết định công nhận hoàn thành tập sự để đăng ký kiểm tra. Quyết định này đã bị cơ quan có thẩm quyền hủy bỏ và A chưa có kết quả mới hợp lệ. Hồ sơ đăng ký được xem xét thế nào?',
  'Tháng 10/2026, A đã đủ thời gian tập sự nhưng quyết định công nhận hoàn thành tập sự sau đó bị hủy. A muốn dùng quyết định cũ để đăng ký kiểm tra lần đầu. Phương án nào phù hợp?',
  'Tháng 10/2026, bản sao quyết định công nhận tập sự của B vẫn còn nguyên dấu, nhưng quyết định đã bị hủy và B chưa có kết quả mới hợp lệ. B cho rằng bản sao vẫn đủ để đăng ký kiểm tra. Hồ sơ cần được xử lý thế nào?'
 ],
 options:{A:['Vẫn được đăng ký vì quyền dự kiểm tra đã phát sinh khi quyết định công nhận được ban hành.','Quyết định công nhận bị hủy thuộc trường hợp không được đăng ký; không chỉ xét lần ban hành ban đầu.'],B:['Được đăng ký lần đầu; việc hủy kết quả chỉ ảnh hưởng những lần đăng ký kiểm tra tiếp theo.','Không có ngoại lệ giữ quyền đăng ký lần đầu theo quyết định đã bị hủy.'],C:['Được đăng ký nếu tổ chức nhận tập sự xác nhận lại đã đủ số tháng, không cần kết quả công nhận mới.','Xác nhận số tháng không khôi phục hiệu lực kết quả công nhận đã bị hủy.'],D:['Chưa được đăng ký theo kết quả đã bị hủy; bản sao quyết định cũ không thay căn cứ hợp lệ.','Điểm a khoản 2 Điều 16 loại người có kết quả công nhận hoàn thành tập sự bị hủy bỏ.']}
},
'SRC26-012':{
 reason:'Bỏ câu dẫn nhắc điều kiện độc lập; các nhiễu là cách khắc phục sai bằng đồng ý, đọc lại hoặc thêm chữ ký.',
 variants:[
  'Tháng 10/2026, bên bán không đọc được nên cần người làm chứng khi công chứng. Người được mời là bên mua trong chính hợp đồng đó, có đầy đủ năng lực hành vi dân sự. Công chứng viên nên xử lý thế nào?',
  'Tháng 10/2026, người bán không đọc được và đề nghị bên mua vừa ký hợp đồng vừa làm chứng. Người mua đủ năng lực; người bán đồng ý bằng văn bản. Phương án nào phù hợp?',
  'Tháng 10/2026, một hồ sơ bán tài sản cần người làm chứng vì bên bán không đọc được. Hai bên chỉ mời người mua, cho rằng người này hiểu hợp đồng và đã được người bán chấp thuận. Hồ sơ còn cần xử lý gì?'
 ],
 options:{A:['Dùng bên mua nếu ghi rõ vai trò kép và để người bán xác nhận đã được giải thích về lợi ích liên quan.','Ghi nhận vai trò và giải thích không khắc phục điều kiện không có quyền, lợi ích, nghĩa vụ liên quan.'],B:['Dùng bên mua nếu người bán ký hoặc điểm chỉ vào văn bản đồng ý chọn người này làm chứng.','Sự đồng ý của người bán không thay các điều kiện bắt buộc đối với người làm chứng.'],C:['Mời người làm chứng khác đủ điều kiện; bên mua không đáp ứng yêu cầu về quyền, lợi ích liên quan.','Bên tham gia chính giao dịch không đáp ứng điều kiện độc lập tại Điều 49.'],D:['Để bên mua đọc toàn bộ dự thảo, công chứng viên chứng kiến rồi tiếp tục mà không cần người khác.','Việc đọc và chứng kiến không thay người làm chứng đủ điều kiện trong trường hợp đã nêu.']}
},
'IMP-T60-062':{
 reason:'Bỏ câu nhắc trực tiếp yêu cầu nhà có sẵn; giữ cách hỏi về đối tượng hiện được đưa vào vốn.',
 variants:[
  'Tháng 10/2026, H đề nghị góp vốn bằng căn nhà chưa xây, sẽ hình thành trong tương lai. Các bên đã thống nhất giá trị phần vốn. Đối tượng nhà ở này có đáp ứng yêu cầu để góp vốn không?',
  'Tháng 10/2026, H mang bản vẽ căn nhà sẽ xây để lập hợp đồng góp vốn với người thân. Người nhận đồng ý chờ hoàn thành nhà. Phương án nào đúng về điều kiện của nhà đưa vào góp vốn?',
  'Tháng 10/2026, dự thảo hợp đồng ghi phần vốn là căn nhà chưa xây và dự kiến giao sau khi hoàn thành. Các bên muốn ký hợp đồng góp vốn ngay. Đối tượng này được đánh giá thế nào?'
 ],
 options:{A:['Chưa đủ điều kiện; nhà góp vốn phải là nhà có sẵn và đáp ứng các yêu cầu luật định.','Điểm b khoản 1 Điều 179 yêu cầu nhà có sẵn và đáp ứng điều kiện tại khoản 1 Điều 160.'],B:['Đủ điều kiện nếu chủ nhà cam kết hoàn thành đúng tiến độ và chịu trách nhiệm khi giao chậm.','Cam kết thực hiện không thay điều kiện nhà có sẵn của đối tượng góp vốn.'],C:['Đủ điều kiện nếu bản vẽ và giá trị phần vốn được các bên thống nhất bằng văn bản.','Thống nhất giá trị không khắc phục điều kiện về đối tượng nhà ở.'],D:['Đủ điều kiện nếu ghi thời điểm chuyển quyền vào lúc nhà hoàn thành thay vì lúc ký hợp đồng.','Lùi thời điểm chuyển quyền không làm căn nhà chưa xây trở thành nhà có sẵn để góp vốn ở hồ sơ này.']}
},
'IMP-T60-079':{
 reason:'Bỏ dẫn tên mốc luật; các phương án chọn giữa định giá, ghi nhận phần vốn và chuyển quyền.',
 variants:[
  'Tháng 10/2026, công ty đã định giá tài sản góp vốn và cấp giấy chứng nhận phần vốn góp cho A. Quyền sở hữu hợp pháp tài sản vẫn chưa chuyển sang công ty. Công ty có thể ghi nhận A đã thanh toán xong phần vốn chưa?',
  'Tháng 10/2026, A đã nhận giấy chứng nhận phần vốn góp sau khi các bên hoàn tất định giá, nhưng chưa chuyển quyền sở hữu hợp pháp tài sản cho công ty. Phần vốn được xác định thế nào?',
  'Tháng 10/2026, hồ sơ đăng ký công ty và biên bản định giá tài sản của A đều hoàn tất. Công ty đã cấp giấy phần vốn góp, còn thủ tục chuyển quyền sở hữu tài sản chưa thực hiện xong. Phương án nào đúng về việc góp vốn?'
 ],
 options:{A:['Đã hoàn tất vì giấy chứng nhận phần vốn góp là sự xác nhận của công ty về việc nhận vốn.','Giấy chứng nhận không thay việc chuyển quyền sở hữu hợp pháp tài sản.'],B:['Đã hoàn tất khi các bên ký biên bản định giá; chuyển quyền là thủ tục thực hiện sau góp vốn.','Định giá xác định giá trị, không phải mốc thay thế chuyển quyền sở hữu.'],C:['Đã hoàn tất khi hồ sơ đăng ký ghi đủ vốn; chỉ cần bổ sung chứng từ chuyển quyền khi có yêu cầu.','Ghi vốn trong hồ sơ không làm tài sản chưa chuyển quyền thành phần vốn đã thanh toán xong.'],D:['Chưa hoàn tất; quyền sở hữu hợp pháp tài sản phải được chuyển sang công ty.','Điều 35 gắn việc thanh toán xong phần vốn bằng tài sản với chuyển quyền sở hữu hợp pháp.']}
},
'DEP26-002':{
 reason:'Giữ câu hỏi riêng về khoản ký cược; thay nhiễu trả gấp đôi bằng nhầm lẫn với khấu trừ và yêu cầu bồi thường.',
 variants:[
  'Tháng 10/2026, A thuê xe và giao 120 triệu đồng ký cược để bảo đảm trả xe. Đến hạn, xe đã bị tiêu hủy nên không còn để trả; các bên không có thỏa thuận khác về ký cược. Riêng khoản 120 triệu này được xử lý thế nào?',
  'Tháng 10/2026, bên thuê không thể hoàn trả xe vì xe đã bị tiêu hủy. Khoản ký cược bảo đảm trả xe là 120 triệu đồng, không có thỏa thuận xử lý khác. Phương án nào đúng về khoản ký cược?',
  'Tháng 10/2026, hợp đồng thuê xe hết hạn khi chiếc xe không còn để trả lại do bị tiêu hủy. A đã giao 120 triệu đồng ký cược và các bên không thỏa thuận cách xử lý khác. Bên cho thuê có quyền gì đối với khoản này?'
 ],
 options:{A:['Chỉ được khấu trừ tiền thuê chưa trả, phần còn lại phải hoàn lại trước khi xem xét thiệt hại về xe.','Nhánh tài sản thuê không còn để trả có quy tắc riêng về tài sản ký cược, không chỉ bảo đảm tiền thuê.'],B:['Bên cho thuê được nhận khoản ký cược 120 triệu đồng.','Khoản 2 Điều 329 quy định tài sản ký cược thuộc bên cho thuê khi tài sản thuê không còn để trả lại.'],C:['Phải hoàn lại ký cược vì hợp đồng đã hết hạn, rồi yêu cầu bồi thường việc mất xe bằng một khoản khác.','Hết hạn thuê không loại quy tắc xử lý ký cược khi không còn xe để trả.'],D:['Chỉ được giữ khoản ký cược chờ xác định đủ thiệt hại, chưa thể áp dụng quy tắc riêng của ký cược.','Không bỏ quy tắc tài sản ký cược thuộc bên cho thuê ở tình huống này; câu hỏi không kết luận hết mọi nghĩa vụ khác.']}
},
'FAM26-020':{
 reason:'Bỏ nêu sẵn ngoại lệ địa bàn; nhấn đúng loại thỏa thuận trước hôn nhân qua hồ sơ.',
 variants:[
  'Tháng 10/2026, hai người chưa kết hôn muốn công chứng thỏa thuận xác lập chế độ tài sản, trong đó có căn nhà ở tỉnh A. Họ chọn văn phòng ở tỉnh B; hồ sơ không phải hợp đồng mua bán hoặc chia nhà. Về địa bàn, văn phòng B có thể tiếp nhận yêu cầu không?',
  'Tháng 10/2026, văn phòng tại B nhận thỏa thuận xác lập chế độ tài sản trước hôn nhân có mô tả nhà ở tỉnh A. Bộ phận tiếp nhận đề nghị chuyển hồ sơ về A chỉ vì vị trí căn nhà. Cách hướng dẫn này có phù hợp không?',
  'Tháng 10/2026, một cặp đôi chưa kết hôn chọn văn phòng tại B để công chứng thỏa thuận xác lập chế độ tài sản về căn nhà ở A. Họ không yêu cầu mua bán hay chia nhà. Phương án nào đúng về nơi công chứng?'
 ],
 options:{A:['Chỉ chọn B nếu bỏ nội dung căn nhà khỏi thỏa thuận và lập văn bản riêng tại A.','Loại thỏa thuận này về bất động sản đã thuộc ngoại lệ, không cần bỏ căn nhà chỉ vì địa bàn.'],B:['Phải chọn A vì mô tả một bất động sản cụ thể làm thỏa thuận trở thành giao dịch theo địa hạt của nhà.','Không đồng nhất việc nêu nhà trong thỏa thuận xác lập chế độ tài sản với mua bán hoặc chia nhà.'],C:['Có thể chọn B nếu một trong hai người thường trú ở B; nếu không thì phải chọn A.','Không có điều kiện phải thường trú tại tỉnh của văn phòng theo ngoại lệ được hỏi.'],D:['Có thể chọn B về mặt địa bàn đối với loại thỏa thuận xác lập chế độ tài sản này.','Điều 44 liệt kê thỏa thuận xác lập chế độ tài sản vợ chồng về bất động sản trong ngoại lệ địa bàn.']}
},
'COMP26-DN-015':{
 reason:'Thay nhiễu chức vụ quản lý, tặng cho có trả tiền bằng các mốc giao dịch và ghi nhận có thể nhầm.',
 variants:[
  'Tháng 10/2026, A nhận tặng cho cổ phần theo giao dịch hợp lệ. Công ty đã nhận hợp đồng nhưng thông tin của A chưa được ghi đầy đủ vào sổ đăng ký cổ đông. A đã trở thành cổ đông ở thời điểm này chưa?',
  'Tháng 10/2026, bên tặng đã chuyển cổ phần cho A theo giao dịch hợp lệ và công ty đã biết việc này. Sổ đăng ký cổ đông còn thiếu thông tin luật định của A. Phương án nào đúng về tư cách cổ đông?',
  'Tháng 10/2026, công ty tiếp nhận hợp đồng tặng cho cổ phần nhưng chưa hoàn tất thông tin người nhận A trong sổ đăng ký cổ đông. A đề nghị xác nhận đã là cổ đông từ ngày ký hợp đồng. Đề nghị đó được xử lý thế nào?'
 ],
 options:{A:['A là cổ đông từ ngày hợp đồng tặng cho có hiệu lực; việc ghi sổ chỉ hoàn thiện hồ sơ nội bộ.','Giao dịch tặng cho hợp lệ không thay mốc ghi đầy đủ thông tin vào sổ đăng ký cổ đông.'],B:['A là cổ đông từ khi công ty nhận được hợp đồng, dù một số thông tin trong sổ chưa được ghi đủ.','Công ty biết hoặc tiếp nhận hợp đồng chưa thay yêu cầu ghi đủ thông tin luật định.'],C:['Chưa đạt mốc trở thành cổ đông; phải ghi đầy đủ thông tin của A vào sổ đăng ký cổ đông.','Khoản 6 đặt mốc người nhận tặng cho trở thành cổ đông khi thông tin được ghi đầy đủ vào sổ.'],D:['A là cổ đông sau khi người đại diện công ty xác nhận việc tặng cho bằng văn bản riêng, không cần hoàn tất sổ.','Không thay yêu cầu ghi sổ bằng một xác nhận riêng của người đại diện.']}
},
'COMP26-DD-011':{
 reason:'Bỏ câu hỏi chỉ sẵn sự đồng ý không hợp pháp hóa; nhiễu là cách áp dụng sai mức tối đa cho giá dịch vụ.',
 variants:[
  'Tháng 10/2026, tỉnh đã ban hành giá tối đa dịch vụ soạn thảo. Văn phòng thỏa thuận với khách mức cao hơn, niêm yết công khai và khách đồng ý vì muốn làm nhanh. Phương án thu này được đánh giá thế nào?',
  'Tháng 10/2026, bảng giá soạn thảo của văn phòng cao hơn mức tối đa do UBND tỉnh quy định. Nhân viên đề nghị giữ mức này nếu khách ký chấp thuận trước. Văn phòng nên xử lý thế nào?',
  'Tháng 10/2026, văn phòng muốn đưa mức giá soạn thảo vượt mức tối đa của tỉnh vào cả bảng niêm yết và hợp đồng dịch vụ. Khách đã đồng ý. Cách xác định mức thu nào phù hợp?'
 ],
 options:{A:['Được thu mức đã thỏa thuận nếu tách phần vượt thành phụ phí soạn thảo nhanh trong cùng dịch vụ.','Đổi tên một phần giá của cùng dịch vụ không loại giới hạn giá tối đa.'],B:['Được thu mức đã thỏa thuận khi hồ sơ công chứng tự nguyện, còn mức tối đa chỉ áp dụng hồ sơ bắt buộc.','Tính tự nguyện công chứng không tạo ngoại lệ cho giới hạn giá dịch vụ đã nêu.'],C:['Phải điều chỉnh giá không vượt mức tối đa, đồng thời thực hiện yêu cầu niêm yết và giải thích.','Niêm yết và đồng thuận của khách không thay yêu cầu tuân thủ mức giá tối đa.'],D:['Được giữ mức thu nếu khách xác nhận đã xem niêm yết và không khiếu nại về giá.','Khách chấp thuận hoặc không khiếu nại không hợp thức hóa giá vượt trần.']}
},
'COMP26-DS-006':{
 reason:'Giữ giới hạn chỉ có căn cứ nhầm lẫn; thay nhiễu vô lý bằng nhầm lẫn về việc xác nhận hoặc giao kết lại.',
 variants:[
  'Tháng 10/2026, một giao dịch có căn cứ nhầm lẫn thuộc Điều 126, không có căn cứ vô hiệu nào khác. Thời hiệu yêu cầu tuyên vô hiệu đã hết mà không ai yêu cầu trong thời hiệu. Hiệu lực giao dịch được xác định thế nào?',
  'Tháng 10/2026, bên giao dịch muốn phủ nhận hiệu lực vì nhầm lẫn nhưng trước đó không yêu cầu tuyên vô hiệu trong thời hiệu. Không có căn cứ vô hiệu độc lập khác. Phương án nào đúng?',
  'Tháng 10/2026, hồ sơ cho thấy giao dịch chỉ vướng căn cứ nhầm lẫn, còn thời hiệu yêu cầu tuyên vô hiệu đã hết mà không có yêu cầu. Một bên cho rằng vẫn phải coi giao dịch chưa có hiệu lực. Nhận định nào phù hợp?'
 ],
 options:{A:['Chỉ có hiệu lực khi các bên ký xác nhận lại sau ngày hết thời hiệu yêu cầu tuyên vô hiệu.','Khoản 2 Điều 132 không đặt thêm việc ký xác nhận lại trong tình huống được hỏi.'],B:['Giao dịch có hiệu lực khi hết thời hiệu mà không có yêu cầu tuyên vô hiệu theo trường hợp này.','Đây là hệ quả tại khoản 2 Điều 132; đề đã loại các căn cứ vô hiệu độc lập khác.'],C:['Vẫn vô hiệu vì có nhầm lẫn; hết thời hiệu chỉ làm mất quyền khởi kiện chứ không ảnh hưởng hiệu lực.','Phương án bỏ quy định cụ thể về hiệu lực giao dịch tại khoản 2.'],D:['Phải có quyết định của Tòa án xác nhận hết thời hiệu thì giao dịch mới được tiếp tục thực hiện.','Không tạo thêm điều kiện phải có quyết định xác nhận như phương án nêu.']}
},
'REFIN26-CC-012':{
 reason:'Viết câu hỏi về cách thực hiện nghĩa vụ; nhiễu giữ các tài liệu có thể bị hiểu nhầm là thay thẻ.',
 variants:[
  'Tháng 10/2026, khách hàng nhận ra công chứng viên quen biết lâu năm và đề nghị bỏ việc xuất trình thẻ để làm hồ sơ nhanh. Công chứng viên nên thực hiện thế nào?',
  'Tháng 10/2026, văn phòng đã niêm yết bản photocopy thẻ công chứng viên tại quầy. Khi tiếp khách, công chứng viên cho rằng không cần xuất trình thẻ nữa. Phương án nào đúng?',
  'Tháng 10/2026, khách đã biết công chứng viên và xem tên người này trên giấy đăng ký hoạt động của văn phòng. Hai bên thống nhất không xuất trình thẻ trong buổi làm việc. Nghĩa vụ của công chứng viên được xác định thế nào?'
 ],
 options:{A:['Chỉ cần xuất trình khi khách chưa biết hoặc có yêu cầu kiểm tra.','Nghĩa vụ xuất trình thẻ khi hành nghề không phụ thuộc yêu cầu hay mức độ quen biết của khách.'],B:['Có thể dùng bản photocopy thẻ đã niêm yết để thay việc xuất trình.','Niêm yết bản sao không tạo ngoại lệ cho việc xuất trình thẻ khi hành nghề.'],C:['Có thể thay bằng giấy đăng ký hoạt động đã ghi tên công chứng viên.','Giấy đăng ký hoạt động của tổ chức không thay nghĩa vụ riêng của từng công chứng viên.'],D:['Vẫn phải xuất trình thẻ khi hành nghề, dù khách quen hoặc đã xem bản niêm yết.','Khoản 1 Điều 38 quy định nghĩa vụ xuất trình thẻ khi hành nghề.']}
},
'REFIN26-CC-017':{
 reason:'Bỏ lời nhắc hai điều kiện đồng thời; nhiễu thử nhầm thời điểm kiểm tra số thành viên và việc thay thế.',
 variants:[
  'Tháng 10/2026, văn phòng hợp danh có hai thành viên. Cả hai đồng ý bằng văn bản để một người rút vốn ngay, chưa có người mới tham gia nên văn phòng sẽ chỉ còn một thành viên. Phương án rút vốn này có thực hiện được không?',
  'Tháng 10/2026, hai thành viên hợp danh đã ký chấp thuận cho một người rút vốn, dự định tìm thành viên thay thế sau. Đến thời điểm rút chưa có người mới. Văn phòng nên giải quyết thế nào?',
  'Tháng 10/2026, một trong hai thành viên văn phòng muốn rút vốn ngay và đã được thành viên còn lại đồng ý. Họ định để người còn lại tiếp tục hoạt động trong lúc tìm người mới. Phương án nào phù hợp?'
 ],
 options:{A:['Chưa được rút theo phương án này; tại thời điểm rút phải bảo đảm còn ít nhất hai thành viên hợp danh.','Tỷ lệ chấp thuận không thay điều kiện số thành viên còn lại tại thời điểm rút vốn.'],B:['Được rút ngay vì chấp thuận bằng văn bản đã đạt toàn bộ số thành viên của văn phòng.','Sự nhất trí mới đáp ứng điều kiện chấp thuận, chưa đáp ứng số thành viên tối thiểu.'],C:['Được rút nếu người rút ký hợp đồng cộng tác để tiếp tục hỗ trợ cho đến khi có thành viên mới.','Cộng tác không duy trì tư cách thành viên hợp danh đã chấm dứt để tính đủ số lượng.'],D:['Được rút trước và bổ sung thành viên sau trong thời hạn văn phòng cam kết với cơ quan quản lý.','Không tự chuyển điều kiện tại thời điểm rút thành thời hạn bổ sung do văn phòng cam kết.']}
},
'REFIN26-CC-019':{
 reason:'Thống nhất diễn giải các mốc dưới hai năm; các nhiễu dựa vào khoản nợ, địa bàn và thời điểm nhận tư cách.',
 variants:[
  'Tháng 10/2026, K muốn hợp danh ở văn phòng khác sau tám tháng kể từ khi tự nguyện rút vốn và chấm dứt tư cách tại văn phòng cũ. Văn phòng cũ không còn nợ. Phương án nào đúng về việc K nhận tư cách mới?',
  'Tháng 10/2026, đã mười tám tháng kể từ khi K tự nguyện rút vốn và chấm dứt tư cách hợp danh. K muốn vào văn phòng khác ngay vì các nghĩa vụ ở nơi cũ đã thanh toán xong. Đề nghị này được xem xét thế nào?',
  'Tháng 10/2026, K nhận lời hợp danh ở tỉnh khác sau một năm từ ngày tự nguyện rút vốn, chấm dứt tư cách tại văn phòng cũ. K viện việc đã trả hết nợ để không phải chờ thêm. Phương án nào phù hợp?'
 ],
 options:{A:['Có thể nhận tư cách mới ngay nếu chứng minh nghĩa vụ tại văn phòng cũ đã được thanh toán xong.','Thanh toán nghĩa vụ không thay thời hạn hai năm của trường hợp đang hỏi.'],B:['Có thể nhận tư cách mới ở tỉnh khác vì thời hạn chờ chỉ áp dụng trong địa bàn nơi cũ.','Không có ngoại lệ đổi tỉnh để bỏ thời hạn này.'],C:['Chưa được hợp danh ở văn phòng khác vì chưa đủ hai năm từ khi chấm dứt tư cách cũ.','Điều 27 áp dụng thời hạn hai năm cho nhánh chấm dứt tư cách nêu trong đề.'],D:['Có thể nhận tư cách trước, nhưng chỉ góp vốn và tham gia quyết định sau khi đủ hai năm.','Trì hoãn góp vốn không làm việc nhận tư cách hợp danh trước thời hạn trở nên phù hợp.']}
},
'CC-025':{
 reason:'Rút câu dài; bỏ lối chỉ dẫn phân biệt và nhiễu cấm toàn bộ giao dịch của người bị hạn chế năng lực.',
 variants:['Tháng 10/2026, K đang bị Tòa án hạn chế năng lực hành vi dân sự. Người đại diện đã đồng ý bằng văn bản để K tự ký một giao dịch tài sản không thuộc sinh hoạt hằng ngày; các điều kiện khác của giao dịch đều đáp ứng. K đồng thời xin bổ nhiệm công chứng viên và đề nghị người đại diện ký cùng lời chứng nếu cần. Hai việc này được đánh giá thế nào?'],
 options:{A:['Giao dịch chỉ được xem xét nếu người đại diện đứng tên thay K; việc bổ nhiệm vẫn chưa đáp ứng điều kiện.','Không đồng nhất yêu cầu người đại diện đồng ý với bắt buộc người đó phải đứng tên thay trong giao dịch đã nêu.'],B:['Giao dịch có thể đáp ứng điều kiện theo dữ kiện; sự đồng ý của đại diện không khắc phục trở ngại bổ nhiệm.','Điều kiện giao dịch theo Điều 24 BLDS và điều kiện bổ nhiệm theo Điều 14 Luật Công chứng là hai vấn đề độc lập.'],C:['Cả hai việc có thể thực hiện nếu người đại diện cùng ký và nhận trách nhiệm về công việc của K.','Đại diện không thể nhận thay tiêu chuẩn năng lực đối với chức danh công chứng viên.'],D:['Giao dịch có thể thực hiện; K cũng được bổ nhiệm nhưng chỉ nhận công chứng các giao dịch có đại diện đồng ý.','Không có cơ chế bổ nhiệm giới hạn theo từng giao dịch để vượt trở ngại về năng lực này.']}
},
'CC-033':{
 reason:'Giữ mốc áp dụng 2027 và hai địa phương; nhiễu nhầm nơi cư trú, cơ quan quyết định và hồ sơ đã nhận.',
 variants:['Từ 01/01/2027, công chứng viên K hành nghề tại tỉnh X, cư trú tại Y. Trong việc miễn nhiệm, K đề nghị cơ quan ở Y giải quyết và lập ủy quyền để người thân ký tiếp lời chứng trong hồ sơ đã nhận ở X sau khi K hết tư cách. Phương án nào đúng?'],
 options:{A:['Thẩm quyền thuộc Chủ tịch tỉnh X; giấy ủy quyền không cho người thân ký lời chứng thay K đã miễn nhiệm.','Thẩm quyền được xác định theo nơi đang hành nghề; ủy quyền không chuyển tư cách công chứng viên của K.'],B:['Thẩm quyền thuộc Chủ tịch tỉnh Y; người thân được ký hồ sơ cũ nếu phạm vi ủy quyền ghi cụ thể.','Nơi cư trú không thay tiêu chí nơi hành nghề; phạm vi ủy quyền không tạo tư cách ký lời chứng.'],C:['Thẩm quyền thuộc Chủ tịch tỉnh X; người thân được ký tiếp hồ sơ đã nhận trước ngày K miễn nhiệm.','Thời điểm tiếp nhận hồ sơ không cho người thân dùng tư cách đã chấm dứt của K để ký.'],D:['Thẩm quyền thuộc Giám đốc Sở Tư pháp X; văn phòng có thể chấp thuận người thân ký để tránh gián đoạn.','Không thay người có thẩm quyền quyết định theo quy định áp dụng, cũng không dùng đồng ý của văn phòng để tạo quyền ký.']}
},
'CC-099':{
 reason:'Tách các yêu cầu trong tình huống chung; giữ giới hạn phần nhà của H và sự đồng ý chưa có của W.',
 variants:['Từ 01/01/2027, nhà chung của H và W ở tỉnh B, còn H đang ở tỉnh A. H muốn công chứng tại A di chúc về phần nhà của mình và văn bản ủy quyền K thực hiện quyền của H đối với nhà. Sau đó K đề nghị ký bán cả nhà tại A khi W chưa đồng ý. Phương án nào phù hợp?'],
 options:{A:['Di chúc và ủy quyền được xét theo ngoại lệ địa bàn; bán nhà vẫn phải xét nơi có nhà, phạm vi quyền K và ý chí W.','Không chuyển ngoại lệ của di chúc, ủy quyền sang hợp đồng bán; H không tự định đoạt phần quyền của W.'],B:['Cả ba việc được thực hiện ở A vì hợp đồng bán do người được ủy quyền ký; vẫn phải có W đồng ý.','Người đại diện ký không làm hợp đồng bán hưởng ngoại lệ địa bàn của văn bản ủy quyền.'],C:['Chuyển hợp đồng bán về B là đủ; giấy ủy quyền của H cho phép K định đoạt toàn bộ nhà chung.','Đúng địa bàn chưa khắc phục việc H không có quyền tự trao cho K phần quyền của W.'],D:['Di chúc, ủy quyền và hợp đồng bán đều phải thực hiện ở B; quyền W chỉ xét khi có tên trên giấy chứng nhận.','Di chúc và ủy quyền có ngoại lệ; quyền đối với tài sản chung không chỉ được xác định từ một tên trên giấy.']}
},
'VER26-035':{
 reason:'Bỏ câu dẫn chỉ sẵn hai bước; nhiễu gần với nhầm lẫn xác nhận, thời điểm công chứng và phạm vi ủy quyền.',
 variants:['Tháng 10/2026, H có quyền sử dụng đất riêng và ký giấy tự viết để nhập vào tài sản chung với W. Việc nhập thuộc loại phải tuân thủ hình thức luật định nhưng chưa hoàn tất. W ủy quyền K bán toàn bộ đất; H chưa ủy quyền bán hoặc trực tiếp tham gia. Công chứng viên nên xử lý hồ sơ thế nào?'],
 options:{A:['Tiếp tục nếu H đã ký giấy nhập chung; W có thể ủy quyền K định đoạt toàn bộ sau khi nhận giấy.','Ý chí trên giấy tự viết chưa thay hình thức bắt buộc; W chưa có căn cứ trao quyền định đoạt toàn bộ.'],B:['Công chứng quyền W cấp trước để hoàn thiện hình thức, rồi dùng quyền đó làm căn cứ bán toàn bộ đất.','Công chứng ủy quyền không khắc phục thiếu hình thức của một giao dịch nhập tài sản khác.'],C:['Chưa thể dựa vào giấy tự viết để coi nhập chung hoàn tất; quyền W cấp chưa đủ cho K bán toàn bộ quyền của H.','Phải kiểm tra hiệu lực việc nhập và phạm vi đại diện; W không tự trao quyền thuộc H.'],D:['Yêu cầu W xác nhận đã nhận tài sản chung để K ký bán, không cần H tham gia thêm vào quyền bán.','Xác nhận của W không thay hình thức việc nhập và quyền định đoạt còn thuộc H.']}
},
'VER26-036':{
 reason:'Rút mệnh đề và bỏ nhiễu ghi lùi ngày; giữ hai văn bản với hai thời điểm, cơ chế riêng.',
 variants:['Tháng 10/2026, A và W xin công chứng việc chia một tài sản chung sau khi kết hôn. Họ đưa kèm thỏa thuận chọn chế độ tài sản lập trước cưới nhưng chưa công chứng, chứng thực; chưa có căn cứ khắc phục thiếu hình thức. Hai người muốn văn bản mới xác nhận thỏa thuận trước cưới đã hợp lệ từ đầu. Phương án nào phù hợp?'],
 options:{A:['Có thể xác nhận hiệu lực từ đầu vì văn bản chia tài sản mới thể hiện hai bên vẫn giữ ý chí đã thỏa thuận.','Ý chí được lặp lại không tự khắc phục hình thức bắt buộc của lựa chọn chế độ tài sản trước hôn nhân.'],B:['Chưa thể công chứng việc chia tài sản chung sau cưới cho đến khi thỏa thuận trước cưới được hợp thức hóa.','Thiếu hình thức của lựa chọn trước cưới không tự loại khả năng xem xét chia tài sản chung theo cơ chế riêng.'],C:['Có thể ghi hai văn bản là một thỏa thuận liên tục, lấy ngày lập bản trước cưới làm ngày áp dụng cho cả hai.','Không đồng nhất hai cơ chế để tạo hiệu lực hồi tố cho văn bản thiếu hình thức.'],D:['Xem xét việc chia theo cơ chế phù hợp; văn bản mới không tự chứng minh thỏa thuận trước cưới đã đủ hình thức.','Điều 47 và Điều 38 đặt yêu cầu riêng; chưa có căn cứ khắc phục thiếu hình thức thì không xác nhận hợp lệ từ đầu chỉ bằng văn bản sau.']}
},
'IMP-T60-012':{
 reason:'Bỏ lời chỉ dẫn phải tách giá trị vật và thiệt hại; nhiễu là ba cách xử lý thiếu một nghĩa vụ.',
 variants:[
  'Tháng 10/2026, bên bán phải giao đúng một bức tranh đã xác định riêng nhưng tranh đã bị hư hỏng. Theo BLDS, trách nhiệm của bên bán về vật và thiệt hại do vi phạm được xác định thế nào?',
  'Tháng 10/2026, bức tranh đặc định mà bên bán phải giao đã bị hư hỏng. Bên bán muốn tự chọn tranh khác cùng giá để thay. Phương án nào đúng về nghĩa vụ khi không giao được bức tranh đã xác định?',
  'Tháng 10/2026, bên mua yêu cầu giải quyết việc bức tranh đã chọn riêng bị hư hỏng trước khi giao. Bên bán cho rằng trả giá trị tranh sẽ giải quyết xong mọi khoản liên quan. Trách nhiệm được xác định thế nào?'
 ],
 options:{A:['Phải thanh toán giá trị vật; nếu vi phạm còn gây thiệt hại thì phải bồi thường theo luật.','Khoản thanh toán giá trị vật và bồi thường thiệt hại do vi phạm không thay thế lẫn nhau.'],B:['Chỉ bồi thường thiệt hại phát sinh, giá trị vật được tính vào đó nếu bên mua chứng minh được tổn thất riêng.','Nghĩa vụ thanh toán giá trị vật ở trường hợp luật nêu không bị thay bằng riêng nghĩa vụ bồi thường khác.'],C:['Được giao bức tranh khác có cùng giá trị để hoàn thành nghĩa vụ, dù bên mua chưa đồng ý.','Không tự thay đối tượng đặc định bằng vật khác khi bên có quyền chưa chấp thuận.'],D:['Chỉ thanh toán giá trị vật, vì khoản này đã thay toàn bộ bồi thường do không giao được tranh.','Thanh toán giá trị vật không loại bồi thường thiệt hại do vi phạm khi đủ căn cứ.']}
},
'IMP-SEP24-046':{
 reason:'Bỏ gợi sẵn kết luận không có giai đoạn ký thêm; nhiễu là nhầm giữa thời hạn hành chính và quyền chứng nhận.',
 variants:['Tháng 10/2026, văn phòng bị thu hồi quyết định cho phép thành lập. Sở Tư pháp dự kiến để văn phòng giữ giấy đăng ký hoạt động thêm 10 ngày làm việc để ký nốt các hồ sơ đã nhận nhưng chưa công chứng. Phương án nào đúng về giấy đăng ký và số hồ sơ này?'],
 options:{A:['Có thể cho ký hết hồ sơ đã nhận đến khi giấy đăng ký hoạt động bị thu hồi, nếu khách hàng đồng ý.','Chưa hoàn tất việc thu hồi giấy đăng ký không tạo quyền ký tiếp sau căn cứ chấm dứt hoạt động đã nêu.'],B:['Thời hạn bảy ngày làm việc là thời gian để ký nốt; chỉ trả lại những hồ sơ còn lại sau mốc đó.','Không biến thời hạn thu hồi giấy thành thời gian tiếp tục chứng nhận.'],C:['Sở thu hồi giấy đăng ký trong bảy ngày làm việc; hồ sơ chưa công chứng được xử lý trả lại, không ký thêm.','Điều 34 quy định thời hạn thu hồi giấy và cách xử lý yêu cầu chưa công chứng khi bị thu hồi.'],D:['Chuyển hồ sơ và giấy đăng ký cho văn phòng khác để nơi đó ký tiếp dưới đăng ký cũ cho đến hết.','Không chuyển giấy đăng ký của tổ chức bị thu hồi để tạo quyền ký tiếp dưới tư cách cũ.']}
},
'IMP-T60-050':{
 reason:'Giữ phạm vi chỉ đánh giá địa giới; bỏ câu hỏi dẫn sẵn hướng phủ định khác xã, giữ điều kiện nguồn đất.',
 variants:[
  'Tháng 10/2026, hai cá nhân muốn chuyển đổi đất nông nghiệp ở hai xã khác nhau trong cùng tỉnh. Nguồn gốc đất thuộc nhóm quy định tại Điều 47. Cơ quan tiếp nhận từ chối riêng vì hai thửa không cùng xã. Căn cứ địa giới này được đánh giá thế nào?',
  'Tháng 10/2026, hồ sơ chuyển đổi đất nông nghiệp giữa hai cá nhân có nguồn đất thuộc Điều 47, nhưng hai thửa nằm ở hai xã cùng tỉnh. Phương án nào đúng về phạm vi địa giới áp dụng cho hồ sơ?',
  'Tháng 10/2026, hai cá nhân có đất nông nghiệp từ nguồn thuộc Điều 47 bị yêu cầu phải cùng xã mới được chuyển đổi, dù hai thửa cùng tỉnh. Các điều kiện khác vẫn đang được kiểm tra. Hướng dẫn về địa giới nào phù hợp?'
 ],
 options:{A:['Cùng tỉnh là đủ cho phép chuyển đổi, không cần kiểm tra thêm nguồn gốc và điều kiện từng thửa.','Phạm vi cùng tỉnh không thay các điều kiện khác của quyền và tài sản.'],B:['Hai thửa khác xã chỉ được làm chuyển nhượng, kể cả khi đủ các điều kiện chuyển đổi còn lại.','Không giữ giới hạn cùng xã để buộc đổi loại giao dịch trái phạm vi cùng tỉnh của điều luật.'],C:['Không từ chối chỉ vì khác xã; phạm vi là cùng đơn vị hành chính cấp tỉnh và vẫn phải xét điều kiện khác.','Điều 47 cho phạm vi cùng tỉnh; Điều 45 và các điều kiện liên quan vẫn phải đáp ứng.'],D:['Có thể bỏ điều kiện không tranh chấp nếu cùng tỉnh và các bên thống nhất giá trị đất tương đương.','Địa giới và thỏa thuận giá không thay yêu cầu về tình trạng tranh chấp.']}
},
'IMP-T60-058':{
 reason:'Viết lại thao tác hồ sơ thay lời nhắc căn cứ và quyền; nhiễu là các cách đổi ý chí vượt phạm vi.',
 variants:['Tháng 10/2026, A tự nguyện trả đất vì không còn nhu cầu và đã lập văn bản, chưa có vi phạm nào được xác định. K chỉ được ủy quyền nộp văn bản. Để áp dụng cách xử lý tài sản khác, K đề nghị đổi lý do thành thu hồi do vi phạm khi A chưa đồng ý. Cơ quan tiếp nhận nên xử lý đề nghị của K thế nào?'],
 options:{A:['Chấp nhận vì quyền nộp hồ sơ bao gồm chọn căn cứ hành chính phù hợp, miễn vẫn trả đúng thửa đất.','Quyền nộp không bao gồm quyền thay ý chí và căn cứ đã thể hiện trong văn bản của A.'],B:['Xem xét theo văn bản tự nguyện của A; K chưa có quyền tự đổi căn cứ từ việc được giao nộp hồ sơ.','Điều 82 xét căn cứ tự nguyện trả đất; Điều 141 BLDS giới hạn quyền K theo nội dung được giao.'],C:['Chuyển sang thu hồi do vi phạm vì việc trả đất cho thấy A đã không còn tiếp tục sử dụng.','Không đồng nhất tự nguyện trả với có vi phạm khi chưa có căn cứ xác định.'],D:['Yêu cầu K ký bổ sung lý do là đủ nếu giấy ủy quyền nộp hồ sơ đã được công chứng.','Công chứng giấy ủy quyền không làm phạm vi nộp hồ sơ tự mở rộng thành thay đổi lý do của A.']}
},
'IMP-SEP24-037':{
 reason:'Bỏ nêu ngay trần 30% trong câu hỏi; để bốn lựa chọn là số tiền cùng đơn vị.',
 variants:['Tháng 10/2026, chủ đầu tư bán nhà hình thành trong tương lai giá 3 tỷ đồng, đã đủ điều kiện bán và đã nhận hợp lệ 150 triệu đồng tiền cọc. Khi ký hợp đồng mua bán, chủ đầu tư đề nghị thu thêm 900 triệu đồng ở lần thanh toán đầu. Số tiền được thu thêm tối đa ở lần này là bao nhiêu?'],
 options:{A:['750 triệu đồng.','Lần thanh toán đầu kể cả cọc không quá 900 triệu; đã nhận 150 triệu nên chỉ thu thêm tối đa 750 triệu.'],B:['900 triệu đồng.','Cách tính này bỏ 150 triệu cọc đã nhận ra ngoài giới hạn lần thanh toán đầu.'],C:['1.050 triệu đồng.','Không cộng riêng khoản cọc 150 triệu thêm vào trần 900 triệu.'],D:['600 triệu đồng.','Đây là kết quả trừ cọc hai lần: hạ trần xuống 25% rồi tiếp tục trừ 150 triệu đã nhận.']}
},
'AUTH26-014':{
 reason:'Bỏ trích sẵn nghĩa vụ và khoản luật; nhiễu thử thời điểm kết thúc, quyền dùng tài liệu và nguồn gây thiệt hại.',
 variants:[
  'Tháng 10/2026, B biết thông tin riêng của A khi thực hiện công việc được ủy quyền. B tự đăng thông tin để quảng bá dịch vụ, không có sự đồng ý hoặc căn cứ pháp luật cho phép. A chứng minh được thiệt hại do việc đăng này. Trách nhiệm của B theo hợp đồng ủy quyền được xác định thế nào?',
  'Tháng 10/2026, sau khi làm xong việc được A ủy quyền, B công khai thông tin riêng đã biết trong quá trình thực hiện để quảng bá. Không có căn cứ cho phép và A đã chứng minh thiệt hại. Phương án nào đúng về nghĩa vụ của B?',
  'Tháng 10/2026, A giao giấy tờ cho B để làm công việc ủy quyền. B dùng thông tin riêng trong giấy tờ cho quảng cáo mà A không đồng ý, không có căn cứ pháp luật cho phép; việc này gây thiệt hại được chứng minh. Yêu cầu bồi thường của A được xem xét thế nào?'
 ],
 options:{A:['B được sử dụng thông tin vì A đã giao tài liệu và không ghi riêng điều khoản cấm quảng bá.','Nghĩa vụ giữ bí mật không chỉ phát sinh khi có điều khoản cấm quảng bá riêng.'],B:['B không còn nghĩa vụ giữ bí mật nếu đã hoàn thành công việc chính trước khi đăng thông tin.','Hoàn thành việc chính không tự cho phép công khai thông tin riêng biết khi thực hiện ủy quyền.'],C:['B chỉ phải gỡ thông tin; thiệt hại ngoài kết quả công việc ủy quyền không thuộc nghĩa vụ bồi thường này.','Khoản 6 Điều 565 đặt trách nhiệm bồi thường thiệt hại do vi phạm các nghĩa vụ, trong đó có giữ bí mật.'],D:['B vi phạm nghĩa vụ giữ bí mật và phải bồi thường thiệt hại do vi phạm đó.','Việc nhận tài liệu để thực hiện ủy quyền không trao quyền tự công khai; đề đã xác định căn cứ vi phạm và thiệt hại.']}
},
'COMP26-DN-001':{
 reason:'Bỏ câu chỉ cách phân biệt và nhiễu chức danh; tập trung thủ tục chuyển quyền với lệ phí trước bạ.',
 variants:[
  'Tháng 10/2026, A góp vốn hợp lệ vào công ty bằng tài sản phải đăng ký quyền sở hữu. Người tiếp nhận yêu cầu vừa sang tên vừa nộp lệ phí trước bạ cho việc chuyển tài sản góp vốn. Phương án nào đúng?',
  'Tháng 10/2026, A dùng ô tô để góp vốn hợp lệ vào công ty TNHH. Hồ sơ cần xác định thủ tục chuyển quyền sở hữu và lệ phí trước bạ đối với việc góp vốn này thế nào?',
  'Tháng 10/2026, công ty nhận xe góp vốn của A và muốn bỏ thủ tục sang tên để tránh lệ phí trước bạ. Đây là giao dịch góp vốn hợp lệ. Công ty nên xử lý thế nào?'
 ],
 options:{A:['Phải chuyển quyền sở hữu; việc chuyển tài sản góp vốn này không phải chịu lệ phí trước bạ.','Điểm a khoản 1 Điều 35 đồng thời đặt thủ tục chuyển quyền và quy định không chịu lệ phí trước bạ.'],B:['Không phải nộp lệ phí nên chỉ cần lập biên bản nhận tài sản, không thực hiện chuyển quyền sở hữu.','Không chịu lệ phí không loại thủ tục chuyển quyền đối với tài sản có đăng ký.'],C:['Phải chuyển quyền và nộp lệ phí như khi mua bán, vì hình thức góp vốn chỉ ảnh hưởng việc hạch toán.','Không đồng nhất chuyển tài sản góp vốn với mua bán để bỏ quy định riêng về lệ phí.'],D:['Chỉ được không nộp lệ phí nếu người góp vốn trở thành người đại diện theo pháp luật của công ty.','Tư cách đại diện không phải điều kiện của quy định không chịu lệ phí đang hỏi.']}
},
'COMP26-DN-002':{
 reason:'Bỏ nhiễu sang tên người quản lý; dùng các nhầm lẫn giữa ghi vốn, chuyển quyền và thay đổi loại hình.',
 variants:[
  'Tháng 10/2026, chủ doanh nghiệp tư nhân dùng chiếc xe thuộc sở hữu của mình phục vụ kinh doanh. Không có giao dịch chuyển quyền nào khác. Người tư vấn yêu cầu sang tên xe cho doanh nghiệp như góp vốn vào công ty TNHH. Yêu cầu này có phù hợp không?',
  'Tháng 10/2026, chiếc xe của chủ doanh nghiệp tư nhân được đưa vào sử dụng trong hoạt động kinh doanh. Hồ sơ bị yêu cầu bổ sung thủ tục chuyển quyền sở hữu từ chủ sang doanh nghiệp. Phương án nào đúng?',
  'Tháng 10/2026, chủ doanh nghiệp tư nhân muốn ghi nhận xe riêng của mình dùng vào kinh doanh. Nhân viên đề nghị làm hợp đồng chuyển quyền cho doanh nghiệp trước khi sử dụng. Không có giao dịch chuyển quyền khác. Hồ sơ cần xử lý thế nào?'
 ],
 options:{A:['Phải chuyển quyền vì ghi tài sản dùng kinh doanh vào vốn sẽ tách tài sản khỏi sở hữu của chủ.','Không áp cơ chế chuyển quyền góp vốn vào công ty cho tài sản chủ doanh nghiệp tư nhân dùng kinh doanh.'],B:['Không phải làm thủ tục chuyển quyền sở hữu cho doanh nghiệp trong trường hợp này.','Điều 35 phân biệt tài sản chủ doanh nghiệp tư nhân dùng kinh doanh với việc góp vốn vào công ty.'],C:['Chỉ phải chuyển quyền nếu xe được ghi nhận vào vốn đầu tư, còn hạch toán chi phí thì không cần.','Không tạo điều kiện chuyển quyền tùy theo cách ghi vốn như phương án nêu.'],D:['Có thể giữ tên chủ nhưng phải đăng ký chiếc xe thành đồng sở hữu giữa chủ và doanh nghiệp.','Không phát sinh yêu cầu tạo đồng sở hữu chỉ từ việc đưa xe vào kinh doanh của doanh nghiệp tư nhân.']}
},
'COMP26-DN-004':{
 reason:'Bỏ câu dẫn nhắc sẵn hai cơ chế; nhiễu gắn đa số, tỷ lệ vốn và người góp tài sản.',
 variants:[
  'Tháng 10/2026, ba sáng lập viên tự định giá tài sản góp vốn khi thành lập công ty, không thuê tổ chức thẩm định giá. Hai người đồng ý mức 5 tỷ đồng, người còn lại phản đối. Kết quả này đã đủ để thông qua giá chưa?',
  'Tháng 10/2026, hồ sơ thành lập công ty có tài sản góp vốn do ba sáng lập viên tự định giá. Biên bản ghi hai người tán thành, một người không đồng ý; không có tổ chức thẩm định giá tham gia. Phương án nào phù hợp?',
  'Tháng 10/2026, hai trong ba sáng lập viên muốn chốt giá tài sản góp vốn theo tỷ lệ trên 50%. Giá do họ tự xác định, người còn lại phản đối và chưa thuê tổ chức thẩm định. Việc định giá được xử lý thế nào?'
 ],
 options:{A:['Được thông qua nếu hai người tán thành chiếm đa số sáng lập viên tham gia định giá.','Tự định giá khi thành lập theo nguyên tắc đồng thuận, không chỉ đa số người.'],B:['Được thông qua nếu người góp chính tài sản đó đồng ý, các sáng lập viên khác chỉ có quyền góp ý.','Người góp tài sản không tự thay sự đồng thuận cần có của nhóm sáng lập viên.'],C:['Được thông qua nếu hai người đồng ý nắm trên 50% vốn, dù không thuê tổ chức thẩm định giá.','Không lấy ngưỡng chấp thuận kết quả của tổ chức thẩm định áp sang tự định giá.'],D:['Chưa được thông qua; tự định giá của các sáng lập viên phải theo nguyên tắc đồng thuận.','Khoản 2 Điều 36 phân biệt tự định giá theo đồng thuận với chấp thuận kết quả thẩm định giá.']}
},
'COMP26-DN-006':{
 reason:'Bỏ diễn giải phủ định dài; nhiễu cùng xoay quanh cách loại thời gian thay vì lý do không liên quan.',
 variants:[
  'Tháng 10/2026, chủ công ty TNHH một thành viên góp tài sản phải chuyển quyền sở hữu. Hồ sơ chứng minh thủ tục hành chính chuyển quyền mất 20 ngày. Khoảng 20 ngày này được tính thế nào trong thời hạn góp vốn 90 ngày?',
  'Tháng 10/2026, khi kiểm tra hạn góp vốn của công ty TNHH một thành viên, người tiếp nhận đếm đủ 90 ngày kể từ cấp đăng ký doanh nghiệp. Trong đó có 20 ngày thực hiện thủ tục hành chính chuyển quyền tài sản góp vốn. Cách tính cần được xử lý thế nào?',
  'Tháng 10/2026, chủ sở hữu công ty TNHH một thành viên có chứng từ về 20 ngày làm thủ tục hành chính chuyển quyền tài sản góp vốn. Không có lý do trì hoãn khác. Phương án nào đúng khi xác định thời hạn góp đủ vốn?'
 ],
 options:{A:['Bắt đầu một thời hạn 90 ngày mới từ ngày hoàn tất thủ tục chuyển quyền sở hữu tài sản.','Luật loại thời gian thực tế làm thủ tục, không khởi động lại toàn bộ thời hạn góp vốn.'],B:['Không tính 20 ngày làm thủ tục hành chính chuyển quyền này vào thời hạn góp vốn.','Thời gian làm thủ tục hành chính chuyển quyền sở hữu tài sản góp vốn thuộc khoảng thời gian được loại.'],C:['Vẫn tính 20 ngày vì chỉ thời gian vận chuyển hoặc nhập khẩu tài sản mới được loại trừ.','Phương án bỏ loại thời gian làm thủ tục hành chính chuyển quyền được luật quy định.'],D:['Chỉ loại 20 ngày nếu cơ quan đăng ký doanh nghiệp đã chấp thuận gia hạn bằng văn bản.','Không tạo thêm điều kiện gia hạn riêng để áp dụng khoảng thời gian được loại theo luật.']}
},
'COMP26-DN-010':{
 reason:'Bỏ câu chỉ sẵn phân biệt quyết định và ký; thay nhiễu người giữ dấu bằng nhầm về nghị quyết và thẩm quyền.',
 variants:[
  'Tháng 10/2026, Hội đồng thành viên đã chấp thuận bán tài sản. Giám đốc là người đại diện theo pháp luật duy nhất; Chủ tịch Hội đồng thành viên không được ủy quyền nhưng muốn ký hợp đồng thay công ty. Hồ sơ cần xử lý thế nào?',
  'Tháng 10/2026, hồ sơ bán tài sản có đủ nghị quyết Hội đồng thành viên, nhưng người dự kiến ký là Chủ tịch. Đăng ký công ty chỉ có Giám đốc là người đại diện theo pháp luật, không có ủy quyền cho Chủ tịch. Phương án nào phù hợp?',
  'Tháng 10/2026, Chủ tịch Hội đồng thành viên viện nghị quyết duyệt bán để ký hợp đồng. Công ty chỉ có Giám đốc là người đại diện theo pháp luật và Chủ tịch chưa được ủy quyền. Nghị quyết này được sử dụng thế nào khi kiểm tra người ký?'
 ],
 options:{A:['Đủ cho Chủ tịch ký nếu Chủ tịch là người ký nghị quyết chấp thuận bán của Hội đồng thành viên.','Ký nghị quyết không tự tạo quyền đại diện công ty để ký hợp đồng bán.'],B:['Chưa đủ cho Chủ tịch ký; cần căn cứ đại diện phù hợp ngoài việc giao dịch đã được chấp thuận.','Thẩm quyền chấp thuận giao dịch khác thẩm quyền đại diện ký hợp đồng.'],C:['Đủ cho Chủ tịch ký khi nghị quyết được toàn bộ thành viên thông qua, dù không trao quyền ký.','Tỷ lệ biểu quyết không thay việc xác định quyền đại diện theo dữ kiện.'],D:['Có thể để Chủ tịch ký nếu Giám đốc ký nháy hồ sơ nội bộ, không cần xác định quyền được giao.','Ký nháy nội bộ không thay căn cứ và phạm vi quyền đại diện còn thiếu.']}
},
'COMP26-CT-001':{
 reason:'Bỏ câu hỏi chỉ cách phân biệt; nhiễu cùng mô tả giá trị chứng thực, không lạc sang bản photocopy.',
 variants:[
  'Tháng 10/2026, A xuất trình bản khai đã được chứng thực chữ ký và nói cơ quan chứng thực đã xác nhận các thông tin kê khai là đúng. Giá trị của việc chứng thực trong trường hợp này được hiểu thế nào?',
  'Tháng 10/2026, bên tiếp nhận coi dấu chứng thực chữ ký trên bản khai của A là bảo đảm toàn bộ sự kiện được nêu. A cũng cho rằng mình không còn chịu trách nhiệm nội dung. Nhận định nào phù hợp?',
  'Tháng 10/2026, một bản kê khai của A có chứng thực chữ ký nhưng nội dung bị tranh luận. A viện dấu chứng thực để khẳng định không cần chịu trách nhiệm về các thông tin đã khai. Phương án nào đúng?'
 ],
 options:{A:['Chứng thực chứng minh chữ ký thuộc A; A vẫn chịu trách nhiệm về nội dung đã kê khai.','Chứng thực chữ ký không đồng nghĩa cơ quan xác minh mọi nội dung kê khai.'],B:['Chứng thực bảo đảm chữ ký và các sự kiện do A kê khai, trừ phần A ghi rõ chỉ là ý kiến.','Không mở rộng phạm vi chứng thực sang việc bảo đảm sự thật của nội dung.'],C:['Chứng thực xác nhận người chứng thực đã đối chiếu và chấp nhận tính đúng đắn của toàn bộ bản khai.','Việc thực hiện thủ tục không biến chứng thực chữ ký thành xác nhận toàn bộ nội dung.'],D:['A chỉ chịu trách nhiệm phần thông tin chưa được người tiếp nhận kiểm tra khi làm chứng thực.','Không chia trách nhiệm nội dung của người khai theo cách kiểm tra của người tiếp nhận.']}
},
'COMP26-CT-011':{
 reason:'Giữ đủ các điều kiện nhưng không gọi sẵn ngoại lệ; thay nhiễu chuyển nhà vô lý bằng hình thức và phạm vi.',
 variants:[
  'Tháng 10/2026, A lập giấy ủy quyền B nhận hồ sơ, không có thù lao, không có nghĩa vụ bồi thường của B và không liên quan chuyển quyền sở hữu tài sản hoặc quyền sử dụng bất động sản. Các điều kiện khác đều đủ. Phương án nào đúng về thủ tục có thể áp dụng?',
  'Tháng 10/2026, giấy ủy quyền chỉ giao B nộp và nhận hồ sơ; không thù lao, không nghĩa vụ bồi thường của B, không chuyển quyền sở hữu tài sản hoặc quyền sử dụng bất động sản. Hồ sơ đáp ứng các điều kiện khác. Có thể giải quyết bằng thủ tục nào?',
  'Tháng 10/2026, bộ phận tiếp nhận từ chối chứng thực chữ ký vì giấy có nội dung ủy quyền. Giấy chỉ giao nộp, nhận hồ sơ, không thù lao, không nghĩa vụ bồi thường của người nhận quyền, không chuyển quyền sở hữu tài sản hay quyền sử dụng bất động sản. Các điều kiện khác đã đủ. Phương án nào phù hợp?'
 ],
 options:{A:['Chứng thực chữ ký đồng thời xác nhận B được làm các việc tiếp theo dù không ghi trong giấy ủy quyền.','Thủ tục chứng thực không tự mở rộng phạm vi đại diện ngoài công việc được giao.'],B:['Không thể chứng thực chữ ký vì giấy có thời hạn thực hiện, dù đáp ứng các điều kiện còn lại.','Việc có thời hạn không tự loại giấy đáp ứng trường hợp được chứng thực chữ ký.'],C:['Có thể chứng thực chữ ký trên giấy ủy quyền theo trường hợp luật cho phép.','Giấy ủy quyền đáp ứng các điều kiện đã nêu thuộc trường hợp ngoại lệ được phép áp dụng.'],D:['Phải công chứng hợp đồng ủy quyền vì có giao việc cho người khác, không được dùng chứng thực chữ ký.','Không bỏ trường hợp giấy ủy quyền được chứng thực chữ ký khi đủ điều kiện.']}
},
'COMP26-CT-014':{
 reason:'Bỏ nêu sẵn ngoại lệ trong câu hỏi; tập trung yêu cầu bằng cấp và thông thạo, không đánh tráo sang miễn thủ tục.',
 variants:[
  'Tháng 10/2026, người dịch có đầy đủ năng lực hành vi và thông thạo một ngôn ngữ không phổ biến nhưng không có bằng đại học thuộc nhóm thông thường luật yêu cầu. Các điều kiện khác không vướng. Thiếu bằng được xem xét thế nào?',
  'Tháng 10/2026, hồ sơ cần dịch tài liệu bằng ngôn ngữ không phổ biến. Người dịch chứng minh được sự thông thạo và có đầy đủ năng lực nhưng không có bằng ngoại ngữ hoặc bằng đại học tương ứng. Phương án nào đúng về tiêu chuẩn này?',
  'Tháng 10/2026, một người thông thạo ngôn ngữ không phổ biến, đủ năng lực và các điều kiện khác, bị đề nghị loại chỉ vì thiếu bằng đại học theo nhóm thông thường. Việc đánh giá tiêu chuẩn người dịch nên thực hiện thế nào?'
 ],
 options:{A:['Không cần xét thông thạo nếu đã xác định ngôn ngữ không phổ biến và người yêu cầu chấp nhận.','Ngoại lệ về bằng cấp không loại yêu cầu thông thạo ngôn ngữ.'],B:['Không loại chỉ vì thiếu bằng; phải áp dụng quy định riêng về ngôn ngữ không phổ biến và sự thông thạo.','Điều 27 có ngoại lệ đối với ngôn ngữ không phổ biến, vẫn giữ yêu cầu năng lực và thông thạo.'],C:['Phải có người dịch thứ hai có bằng ký cùng để bù điều kiện bằng cấp còn thiếu.','Không tự thêm cơ chế ký cùng người có bằng thay cho việc áp dụng ngoại lệ luật định.'],D:['Chỉ được dịch nếu cơ quan chứng thực đồng ý miễn điều kiện bằng cấp bằng một quyết định riêng.','Không biến trường hợp luật cho phép thành quyền miễn tùy từng hồ sơ bằng quyết định riêng.']}
},
'COMP26-TS-004':{
 reason:'Bỏ nhiễu bất kỳ giờ hoặc chỉ ngày kiểm tra; thử nhầm tổng giờ, sản phẩm và lịch thực tập.',
 variants:[
  'Tháng 10/2026, người tập sự chỉ muốn đến văn phòng một buổi mỗi tuần, dù lịch làm việc của tổ chức đã xác định nhiều ngày và không có điều chỉnh hợp lệ khác. Nghĩa vụ về thời gian được thực hiện thế nào?',
  'Tháng 10/2026, người tập sự đề nghị chỉ làm vào cuối tuần, trong khi tổ chức nhận tập sự có ngày, giờ làm việc khác và chưa điều chỉnh hợp lệ. Phương án nào phù hợp?',
  'Tháng 10/2026, nhật ký của người tập sự ghi đủ tổng số giờ, nhưng người này thường không đến vào ngày, giờ làm việc của tổ chức. Không có căn cứ điều chỉnh hợp lệ. Việc đáp ứng nghĩa vụ thời gian được đánh giá thế nào?'
 ],
 options:{A:['Chỉ cần giao đủ số hồ sơ được phân công, lịch có mặt có thể tự bố trí ngoài giờ làm việc.','Số sản phẩm không thay nghĩa vụ bảo đảm thời gian theo ngày, giờ làm việc của tổ chức.'],B:['Được tự đổi lịch nếu tổng giờ trong nhật ký bằng tổng giờ dự kiến của thời gian tập sự.','Ghi đủ tổng giờ không tự hợp thức lịch khác khi không có điều chỉnh hợp lệ.'],C:['Chỉ cần người hướng dẫn xác nhận công việc đã hoàn thành, không phải xét các buổi vắng theo lịch.','Xác nhận hoàn thành công việc không thay điều kiện về thời gian làm việc.'],D:['Phải bảo đảm thời gian tập sự theo ngày, giờ làm việc của tổ chức nhận tập sự.','Khoản 4 gắn nghĩa vụ thời gian với ngày, giờ làm việc của tổ chức theo trường hợp đã nêu.']}
},
'COMP26-DAT-001':{
 reason:'Giữ tình trạng biện pháp khẩn cấp độc lập; thay nhiễu giá Nhà nước bằng cách xử lý hồ sơ dễ nhầm.',
 variants:[
  'Tháng 10/2026, tranh chấp đất đã được giải quyết bằng bản án có hiệu lực, nhưng quyền sử dụng đất vẫn đang chịu biện pháp khẩn cấp tạm thời. Các bên đề nghị chuyển nhượng ngay. Phương án nào đúng về điều kiện hồ sơ?',
  'Tháng 10/2026, hồ sơ chuyển nhượng có bản án có hiệu lực giải quyết xong tranh chấp. Quyết định áp dụng biện pháp khẩn cấp tạm thời đối với quyền sử dụng đất vẫn còn. Công chứng viên nên xử lý thế nào?',
  'Tháng 10/2026, người bán viện bản án đã giải quyết tranh chấp để yêu cầu tiếp tục chuyển nhượng. Hồ sơ vẫn có biện pháp khẩn cấp tạm thời đang áp dụng với quyền sử dụng đất. Phương án nào phù hợp?'
 ],
 options:{A:['Có thể chuyển nhượng nếu bên mua xác nhận đã biết biện pháp và nhận mọi rủi ro liên quan.','Thỏa thuận chịu rủi ro không thay điều kiện pháp luật về biện pháp đang áp dụng.'],B:['Có thể ký trước rồi chỉ đăng ký chuyển quyền sau khi biện pháp được chấm dứt.','Không tự lùi việc kiểm tra điều kiện sang giai đoạn đăng ký để bỏ trở ngại hiện tại.'],C:['Chưa đủ điều kiện; việc hết tranh chấp không tự loại biện pháp khẩn cấp tạm thời đang áp dụng.','Điều 45 đặt các điều kiện đồng thời, phải kiểm tra riêng tình trạng biện pháp khẩn cấp.'],D:['Có thể chuyển nhượng vì bản án có hiệu lực giải quyết tranh chấp đã thay quyết định về biện pháp trước đó.','Dữ kiện xác định biện pháp vẫn còn; không suy tự hết hiệu lực chỉ từ bản án giải quyết tranh chấp.']}
},
'REFIN26-CC-003':{
 reason:'Bỏ nhắc tên nguyên tắc; nhiễu dùng cách suy tỷ lệ vốn thành quyền quyết định.',
 variants:[
  'Tháng 10/2026, hai thành viên hợp danh của văn phòng góp vốn theo tỷ lệ 80% và 20%. Người góp 80% đề nghị có quyền quyết định gấp bốn lần người còn lại. Phương án nào đúng về quyền quyết định các vấn đề của văn phòng?',
  'Tháng 10/2026, dự thảo nội quy quy đổi phần vốn 80% thành bốn phiếu và phần vốn 20% thành một phiếu. Cả hai đều là công chứng viên hợp danh; câu hỏi không xét chia lợi nhuận. Cách phân bổ quyền quyết định này được đánh giá thế nào?',
  'Tháng 10/2026, khi quyết định vấn đề của văn phòng, một thành viên hợp danh viện phần vốn 80% để yêu cầu quyền cao hơn thành viên góp 20%. Phương án nào phù hợp với tư cách của hai người?'
 ],
 options:{A:['Theo tỷ lệ 4:1 đối với quản trị; chỉ quyết định nghiệp vụ công chứng mới có quyền ngang nhau.','Không tự tách các vấn đề quản trị khỏi phạm vi quyền ngang nhau của thành viên hợp danh.'],B:['Người góp 20% chỉ có quyền ngang nhau nếu điều lệ cho phép hoặc đã bổ sung vốn đến bằng nhau.','Quyền ngang nhau không phụ thuộc bù vốn hoặc việc điều lệ tự trao thêm quyền.'],C:['Hai thành viên hợp danh có quyền ngang nhau khi quyết định các vấn đề của văn phòng.','Điều 23 đặt nguyên tắc quyền ngang nhau, không quy đổi theo tỷ lệ vốn.'],D:['Áp dụng theo tỷ lệ vốn nếu nội quy được cả hai ký, vì đã có sự đồng ý của người góp ít.','Thỏa thuận nội quy không thay nguyên tắc luật định về quyền quyết định.']}
},
'REFIN26-CC-009':{
 reason:'Sửa câu thiếu trôi chảy và chữ thường sau dấu chấm; nhiễu cùng xoay quanh giao ký và tư cách đại diện.',
 variants:[
  'Tháng 10/2026, Phó phòng công chứng được giao ký thay một văn bản nội bộ. Trưởng phòng không thay đổi, nhưng bên giao dịch muốn ghi Phó phòng là người đại diện theo pháp luật chỉ từ văn bản đó. Thông tin đại diện được xác định thế nào?',
  'Tháng 10/2026, hồ sơ của Phòng công chứng có văn bản nội bộ do Phó phòng ký thay. Không có thay đổi chức danh Trưởng phòng. Phương án nào đúng về người đại diện theo pháp luật của Phòng?',
  'Tháng 10/2026, Phó phòng được giao ký một việc nội bộ và cho rằng từ đó mình thay Trưởng phòng làm đại diện theo pháp luật. Người lập hồ sơ giao dịch cần xác định tư cách này thế nào?'
 ],
 options:{A:['Trưởng phòng vẫn là đại diện theo pháp luật; việc giao ký một việc không tự thay tư cách này.','Điều 20 xác định Trưởng phòng là đại diện theo pháp luật, khác quyền ký một việc được giao.'],B:['Phó phòng là đại diện theo pháp luật trong thời gian văn bản giao ký thay còn hiệu lực.','Không đồng nhất thời hạn giao ký với thay đổi người đại diện theo pháp luật.'],C:['Cả Trưởng phòng và Phó phòng trở thành đại diện theo pháp luật vì cùng có quyền ký văn bản của Phòng.','Có quyền ký theo phạm vi được giao không tự tạo thêm người đại diện theo pháp luật.'],D:['Người ký văn bản mới nhất của Phòng là đại diện cho giao dịch tiếp theo nếu chưa có thông báo khác.','Không xác định tư cách đại diện theo thứ tự văn bản được ký.']}
},
'REFIN26-QT-010':{
 reason:'Rút câu hỏi và thay các nhiễu bằng cách thông báo thiếu hình thức hoặc thiếu người nhận.',
 variants:[
  'Tháng 10/2026, văn phòng đã sửa đúng một lỗi đánh máy không ảnh hưởng quyền, nghĩa vụ rồi chỉ gọi điện báo các bên. Còn phải thực hiện yêu cầu thông báo nào?',
  'Tháng 10/2026, việc sửa lỗi kỹ thuật đã thực hiện đúng; lỗi không ảnh hưởng quyền, nghĩa vụ. Văn phòng mới gọi điện thông tin cho người tham gia giao dịch. Phương án nào phù hợp?',
  'Tháng 10/2026, công chứng viên đã sửa đúng lỗi in số không ảnh hưởng quyền, nghĩa vụ. Văn phòng mới nhắn các bên đến nghe giải thích, chưa gửi thông báo bằng văn bản. Việc thông báo còn cần xử lý thế nào?'
 ],
 options:{A:['Chỉ cần lưu ghi âm cuộc gọi nếu đã liên hệ được đầy đủ người tham gia giao dịch.','Liên hệ đủ người qua điện thoại không thay hình thức thông báo bằng văn bản.'],B:['Thông báo bằng văn bản cho người tham gia giao dịch trong thời hạn luật định.','Điều 52 yêu cầu hình thức văn bản và đúng thời hạn đối với người tham gia.'],C:['Niêm yết nội dung sửa tại văn phòng, vì không thay quyền và nghĩa vụ của các bên.','Niêm yết không thay thông báo đến người tham gia theo yêu cầu đang hỏi.'],D:['Gửi văn bản cho người đang giữ bản gốc; những người còn lại chỉ cần nhận điện thoại.','Không giới hạn người nhận văn bản thông báo vào người đang giữ bản gốc.']}
},
'REFIN26-QT-015':{
 reason:'Bỏ nhiễu người làm chứng; thử xác định đúng chủ thể kế thừa thay vì chức danh hay con dấu cũ.',
 variants:[
  'Tháng 10/2026, pháp nhân từng yêu cầu công chứng đã chấm dứt hoạt động. Chủ thể kế thừa quyền, nghĩa vụ đã được xác định và đồng ý cấp bản sao cho người liên quan, nhưng giám đốc cũ phản đối với tư cách cá nhân. Căn cứ đồng ý được xác định thế nào?',
  'Tháng 10/2026, người có quyền, nghĩa vụ liên quan xin bản sao giao dịch của pháp nhân đã chấm dứt. Chủ thể kế thừa đã đồng ý, còn người giữ con dấu cũ phản đối và nhận mình có quyền quyết định. Phương án nào đúng về sự đồng ý?',
  'Tháng 10/2026, hồ sơ xin bản sao có sự đồng ý của chủ thể kế thừa quyền, nghĩa vụ một pháp nhân đã chấm dứt. Giám đốc cũ yêu cầu phải có thêm chấp thuận riêng của mình. Yêu cầu này được xem xét thế nào?'
 ],
 options:{A:['Phải có thêm người từng đại diện pháp nhân ký giao dịch đồng ý, dù chủ thể kế thừa đã xác định.','Không giữ quyền đồng ý riêng theo chức danh cũ khi pháp nhân đã chấm dứt và có chủ thể kế thừa.'],B:['Theo người đang giữ con dấu cũ, vì đây là dấu hiệu còn quản lý hồ sơ pháp nhân.','Giữ con dấu không chứng minh có quyền kế thừa để quyết định.'],C:['Theo sự đồng ý của chủ thể kế thừa quyền, nghĩa vụ của pháp nhân.','Quy định chuyển căn cứ đồng ý sang chủ thể kế thừa khi pháp nhân yêu cầu công chứng đã chấm dứt.'],D:['Cần đồng thời chủ thể kế thừa và giám đốc cũ đồng ý để bảo đảm không có tranh chấp.','Không tự thêm chấp thuận bắt buộc của giám đốc cũ chỉ vì người này phản đối với tư cách cá nhân.']}
},
'REFIN26-QT-024':{
 reason:'Đổi câu hỏi có/không dẫn lộ đáp án thành phương án xử lý; nhiễu là thủ tục quản lý không thay phán quyết.',
 variants:[
  'Tháng 10/2026, công chứng viên phát hiện giao dịch mình đã công chứng có dấu hiệu vi phạm pháp luật. Một bên đề nghị văn phòng đóng dấu xác nhận văn bản vô hiệu ngay. Công chứng viên có thể xử lý theo cách nào?',
  'Tháng 10/2026, sau khi công chứng xong, người thực hiện phát hiện căn cứ cho rằng giao dịch vi phạm pháp luật. Phương án nào phù hợp để yêu cầu xem xét hiệu lực văn bản?',
  'Tháng 10/2026, khách đề nghị công chứng viên xóa hiệu lực văn bản đã công chứng vì có dấu hiệu vi phạm. Công chứng viên cần lựa chọn cách xử lý nào trong phạm vi quyền của mình?'
 ],
 options:{A:['Ra thông báo vô hiệu với tư cách người đã công chứng, sau đó gửi cho các bên biết để thực hiện.','Người đã công chứng không vì thế có quyền thay Tòa án tuyên vô hiệu.'],B:['Gửi báo cáo vi phạm cho Sở Tư pháp để văn bản ngừng có hiệu lực ngay từ lúc báo cáo được nhận.','Báo cáo quản lý không tự làm phát sinh phán quyết về hiệu lực văn bản.'],C:['Thu hồi toàn bộ bản gốc và xóa số công chứng để thay việc yêu cầu giải quyết hiệu lực.','Thu hồi bản gốc hoặc xử lý sổ không thay cơ chế giải quyết hiệu lực theo thẩm quyền.'],D:['Đề nghị Tòa án tuyên văn bản vô hiệu khi có căn cứ; không tự ra quyết định thay Tòa án.','Điều 54 trao quyền đề nghị, không phải quyền tự tuyên vô hiệu.']}
},
'REFIN26-DAT-002':{
 reason:'Bỏ dẫn sẵn nhóm quyền; các nhiễu tập trung sự khác nhau giữa trả tiền một lần và thuê lại.',
 variants:[
  'Tháng 10/2026, cá nhân thuê lại đất trong khu công nghiệp đã trả tiền một lần cho cả thời gian thuê, muốn thế chấp quyền sử dụng đất và tài sản thuộc sở hữu của mình. Các điều kiện giao dịch khác đều đủ. Phương án nào phù hợp về quyền thế chấp?',
  'Tháng 10/2026, ngân hàng nhận đề nghị thế chấp từ cá nhân thuê lại đất khu công nghiệp, đã trả tiền một lần toàn kỳ. Người này có tài sản hợp pháp trên đất và đáp ứng các điều kiện khác. Nhóm quyền được xem xét theo cách nào?',
  'Tháng 10/2026, hồ sơ thế chấp của cá nhân thuê lại đất khu công nghiệp bị từ chối chỉ vì là thuê lại. Tiền thuê đã trả một lần cho cả thời gian; điều kiện giao dịch khác đều đủ. Cách xác định quyền nào đúng?'
 ],
 options:{A:['Không có quyền thế chấp quyền sử dụng đất vì không trực tiếp thuê của Nhà nước, dù đã trả một lần.','Không tự loại thuê lại khỏi nhánh trả tiền một lần được khoản 3 Điều 37 dẫn chiếu.'],B:['Chỉ được thế chấp tài sản trên đất; trả tiền một lần không ảnh hưởng nhóm quyền của người thuê lại.','Phương thức trả tiền là yếu tố phân biệt nhóm quyền trong điều luật.'],C:['Xét nhóm quyền ở khoản 1 Điều 37, bao gồm quyền thế chấp khi đủ điều kiện.','Khoản 3 dẫn trường hợp trả tiền một lần cho cả thời gian về nhóm quyền khoản 1.'],D:['Xét như trả tiền hằng năm vì khoản tiền một lần được phân bổ dần theo từng năm sử dụng.','Hạch toán phân bổ không đổi phương thức trả tiền đã xác định trong dữ kiện.']}
},
'REFIN26-DAT-006':{
 reason:'Bỏ chỉ dẫn về nhánh luật; nhiễu là thủ tục cấp giấy và đăng ký dễ nhầm với cập nhật sổ.',
 variants:[
  'Tháng 10/2026, tất cả người thừa kế quyền sử dụng đất đều thuộc nhóm không được cấp giấy chứng nhận theo khoản 3 Điều 44. Họ chưa chuyển nhượng hoặc tặng cho đất và muốn làm hồ sơ nhận thừa kế. Bước hồ sơ nào phù hợp?',
  'Tháng 10/2026, nhóm người thừa kế thuộc khoản 3 Điều 44 chưa định đoạt quyền sử dụng đất. Bộ phận tiếp nhận yêu cầu họ phải được cấp giấy chứng nhận rồi mới làm hồ sơ thừa kế. Phương án nào đúng?',
  'Tháng 10/2026, những người thừa kế thuộc nhóm không được cấp giấy chứng nhận muốn cập nhật việc nhận thừa kế, chưa bán hoặc tặng cho đất. Hồ sơ về người nộp và mục đích đăng ký nên được xử lý thế nào?'
 ],
 options:{A:['Phải xin cấp giấy chứng nhận cho nhóm người thừa kế trước rồi mới được ghi nhận thừa kế.','Không đặt bước cấp giấy trái giới hạn chủ thể để thay cơ chế cập nhật sổ.'],B:['Chỉ cần lập văn bản nhận thừa kế và giữ cùng giấy tờ đất, chưa cần nộp hồ sơ khi chưa định đoạt.','Điều luật có cơ chế nộp hồ sơ cập nhật Sổ địa chính dù chưa chuyển nhượng hoặc tặng cho.'],C:['Người thừa kế hoặc đại diện được ủy quyền bằng văn bản nộp hồ sơ nhận thừa kế để cập nhật Sổ địa chính.','Điểm c khoản 3 Điều 44 quy định chủ thể nộp và mục đích cập nhật trong trường hợp này.'],D:['Phải hoàn tất chuyển nhượng hoặc tặng cho trước rồi người nhận mới được nộp hồ sơ thừa kế.','Không bắt buộc định đoạt trước để sử dụng cơ chế cập nhật thừa kế khi chưa định đoạt.']}
}
};

const explanations={
 'IMP-T60-058':'Điều 82 Luật Đất đai có căn cứ thu hồi do người sử dụng tự nguyện trả lại đất bằng văn bản. Hồ sơ chưa xác định vi phạm thì không đổi sang căn cứ vi phạm chỉ để chọn hệ quả xử lý tài sản khác. Theo phạm vi đại diện tại Điều 141 BLDS, K được giao nộp hồ sơ chứ chưa được thay đổi ý chí hoặc lý do A đã thể hiện.',
 'COMP26-DN-010':'Hội đồng thành viên chấp thuận bán tài sản là một yêu cầu về quyết định giao dịch. Người đại diện ký hợp đồng lại phải được xác định theo tư cách và phạm vi quyền phù hợp. Trong đề, chỉ Giám đốc là đại diện theo pháp luật và Chủ tịch chưa có ủy quyền. Việc Chủ tịch ký nghị quyết hoặc giao dịch được thông qua đủ phiếu không tự trao quyền ký hợp đồng.',
 'REFIN26-CC-003':'Điều 23 Luật Công chứng quy định thành viên hợp danh có quyền ngang nhau khi quyết định các vấn đề của văn phòng. Tỷ lệ góp vốn 80% và 20% không được tự đổi thành tỷ lệ phiếu 4:1. Cần tách quyền quyết định này với việc xem xét các lợi ích kinh tế theo căn cứ riêng; câu hỏi không xác định cách chia lợi nhuận.',
 'REFIN26-CC-009':'Điều 20 Luật Công chứng xác định Trưởng phòng là người đại diện theo pháp luật của Phòng công chứng. Phó phòng được giao ký một việc chỉ có quyền trong phạm vi được giao, không vì chữ ký đó mà tự thay Trưởng phòng về tư cách đại diện theo pháp luật. Phải xác định riêng tư cách và phạm vi ký khi lập hồ sơ.',
 'COMP26-CT-011':'Các điều kiện trong giấy ủy quyền đáp ứng trường hợp được chứng thực chữ ký theo Điều 24 và Điều 25 của quy định về chứng thực. Không bỏ trường hợp này chỉ vì văn bản có nội dung ủy quyền hoặc có thời hạn. Tuy nhiên, B vẫn chỉ được thực hiện công việc trong phạm vi đã giao; dấu chứng thực không tự bổ sung quyền khác.',
 'COMP26-CT-014':'Điều 27 có quy định riêng cho người dịch ngôn ngữ không phổ biến: thiếu bằng thuộc nhóm thông thường không phải lý do tự loại nếu đáp ứng yêu cầu về năng lực và sự thông thạo. Không thêm điều kiện phải có người có bằng ký bù hoặc quyết định miễn riêng. Thủ tục chứng thực chữ ký người dịch tại Điều 31 vẫn là bước cần thực hiện theo quy định.',
 'IMP-T60-050':'Điều 47 Luật Đất đai xác định phạm vi chuyển đổi trong cùng đơn vị hành chính cấp tỉnh đối với nguồn đất thuộc nhóm quy định. Vì vậy không từ chối chỉ do hai thửa ở khác xã. Việc cùng tỉnh chưa thay các yêu cầu về chủ thể, nguồn gốc và tình trạng đất, trong đó có điều kiện tại Điều 45; hồ sơ vẫn phải được kiểm tra đầy đủ.',
 'CC-033':'Theo quy định áp dụng từ 01/01/2027, thẩm quyền trong tình huống miễn nhiệm này được xác định theo tỉnh nơi K đang hành nghề, không phải tỉnh cư trú. Sau khi K hết tư cách, giấy ủy quyền không chuyển chức danh và quyền ký lời chứng dưới tên K cho người thân. Thời điểm hồ sơ đã được tiếp nhận cũng không tạo ngoại lệ ký thay đó.',
 'CC-099':'Di chúc và ủy quyền thực hiện quyền đối với bất động sản thuộc trường hợp ngoại lệ về địa bàn. Hợp đồng bán nhà thông thường không được hưởng cùng ngoại lệ chỉ vì K ký theo đại diện. Đối với nhà chung, H chỉ có thể trao quyền thuộc mình; việc bán cả nhà còn phải kiểm tra quyền của W và sự đồng ý còn thiếu. Đúng địa bàn không thay điều kiện về quyền định đoạt.'
};
for(const [id,explanation] of Object.entries(explanations))module.exports[id].explanation=explanation;
